const { TypeScriptVersion } = require('@definitelytyped/typescript-versions');
const {
    cleanTypeScriptInstalls,
    typeScriptPath
} = require('@definitelytyped/utils');
const { runTsCompile } = require('./pre-publish');
const globby = require('globby');
const semver = require('semver');
const fs = require('fs-extra');
const path = require('path');
const { exec } = require('child_process');

const MIN_VERSION = '3.5.0';

/**
 * All the TypeScript versions we promise to support, from `MIN_VERSION` up to
 * the newest shipped compiler. `@definitelytyped/utils` only exposes an
 * "install everything" helper, which also downloads the pre-3.5 compilers that
 * we never exercise. Resolving the list ourselves keeps `install` and `test`
 * on exactly the same set of versions.
 */
function getTestedTsVersions() {
    return TypeScriptVersion.shipped.filter(function (version) {
        return !semver.lt(version + '.0', MIN_VERSION);
    });
}

function execAsync(cmd, cwd) {
    return new Promise((resolve, reject) => {
        exec(cmd, { encoding: 'utf8', cwd }, (err, stdout, stderr) => {
            if (stderr) {
                console.error(stderr);
            }
            err ? reject(err) : resolve(stdout);
        });
    });
}

async function installTsVersion(version) {
    // `typeScriptPath` points at `<installDir>/node_modules/typescript`.
    const installDir = path.resolve(typeScriptPath(version), '..', '..');
    if (await fs.pathExists(installDir)) {
        return;
    }
    console.log(`Installing ts version ${version} to ${installDir} ...`);
    await fs.mkdirp(installDir);
    await fs.writeJson(path.join(installDir, 'package.json'), {
        description: `Installs typescript@${version}`,
        repository: 'none',
        license: 'MIT',
        dependencies: {
            typescript: version === 'next' ? 'next' : `${version}.x`
        }
    });
    await execAsync(
        'npm install --ignore-scripts --no-shrinkwrap --no-package-lock --no-bin-links',
