        else {
            bg.removeTextContent();
        }

        bg.setStyle(normalStyle);

        bg.ensureState('emphasis').style = emphasisStyle;
        bg.ensureState('blur').style = blurStyle;
        bg.ensureState('select').style = selectStyle;
        setDefaultStateProxy(bg);
    }

    group.add(bg);
}

